#include <stdio.h>
#include <string.h>

int main(void) {
    char mensagem[512];

    if (fgets(mensagem, sizeof(mensagem), stdin) == NULL) {
        return 0;
    }

    int divertido = 0;
    int chateado = 0;
    size_t tamanho = strlen(mensagem);

    for (size_t i = 0; i + 2 < tamanho; i++) {
        if (mensagem[i] == ':' && mensagem[i + 1] == '-') {
            if (mensagem[i + 2] == ')') {
                divertido++;
            } else if (mensagem[i + 2] == '(') {
                chateado++;
            }
        }
    }

    if (divertido == chateado) {
        printf("neutro\n");
    } else if (divertido > chateado) {
        printf("divertido\n");
    } else {
        printf("chateado\n");
    }

    return 0;
}
```

